(function(){const L=window.LG;const keys=L.areas.map((a)=>a[0]);const f1=d3.format('.1f');const heat=(v)=>v>=8?'#B1E287':v>=5?'#F3EC9E':'#F2C2B3';const areaRow=(k)=>L.rows('latest').find((r)=>r.area===k);const mk=(tag,cls,txt)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(txt!=null)e.textContent=txt;return e;};
const twoStep=(btn,label,fn)=>{btn.textContent=label;let armed=false;btn.onclick=async()=>{if(!armed){armed=true;btn.textContent='Tap again to confirm';setTimeout(()=>{armed=false;btn.textContent=label;},3500);return;}btn.disabled=true;try{await fn();}catch(e){btn.disabled=false;btn.textContent='Didn’t work, try again';}};};
dash.onData(()=>{const h=dash.data('history');const known=h.status==='ok';const has=known&&Array.isArray(h.data)&&h.data.length>0;document.querySelectorAll('.lg [data-when=data]').forEach((el)=>{el.hidden=!has;});document.querySelectorAll('.lg [data-when=empty]').forEach((el)=>{el.hidden=!known||has;});});
dash.draw('val',(el)=>{const r=L.rows(el.dataset.source)[0];const f=el.dataset.field;const v=r?r[f]:null;el.classList.remove('lg-up','lg-down');if(v===null||v===undefined){el.textContent=L.none;return;}if(f==='month'||f==='since'){el.textContent=L.monthLabel(v);}else if(f==='avg'||f==='allTime'){el.textContent=f1(v);}else if(f==='change'){el.textContent=(v>0?'+':v<0?'-':'')+f1(Math.abs(v));if(v>0)el.classList.add('lg-up');if(v<0)el.classList.add('lg-down');}else if(f==='rate'){el.textContent=v+'%';}else if(f==='week'){el.textContent=L.weekLabel(v);}else{el.textContent=String(v);}});
dash.draw('area',(el)=>{const r=areaRow(el.dataset.area);el.textContent=r&&r.score!=null?String(r.score):L.none;});
dash.draw('areachg',(el)=>{const r=areaRow(el.dataset.area);const c=r?r.change:null;el.classList.remove('lg-up','lg-down');if(c==null){el.textContent='';return;}el.textContent=(c>0?'+':c<0?'-':'')+Math.abs(c);if(c>0)el.classList.add('lg-up');if(c<0)el.classList.add('lg-down');});
dash.draw('areabar',(el)=>{const r=areaRow(el.dataset.area);let s=el.firstElementChild;if(!s){s=document.createElement('span');el.replaceChildren(s);}s.style.width=(r&&r.score!=null?r.score*10:0)+'%';});
dash.draw('wheel',(el)=>{const l=dash.data('latest');const rows=L.rows('latest');el.replaceChildren();if(!rows.length||rows.every((d)=>d.score==null)){L.empty(el,l.status==='error'?'Your wheel couldn’t load.':l.status==='loading'?'Loading…':'Your wheel appears after your first monthly check-in.');return;}const W=Math.max(260,el.clientWidth||320);const H=Math.min(W,440);const pad=W<420?80:96;const R=Math.max(56,Math.min(W,H)/2-pad);const cx=W/2,cy=H/2;const n=rows.length;const ang=(i)=>-Math.PI/2+(i*2*Math.PI)/n;const s=d3.scaleLinear().domain([0,10]).range([0,R]);const pt=(i,v)=>[cx+Math.cos(ang(i))*s(v),cy+Math.sin(ang(i))*s(v)];const svg=d3.select(el).append('svg').attr('viewBox',`0 0 ${W} ${H}`).attr('width','100%').attr('role','img').attr('aria-label','Wheel of life for the latest month: '+rows.map((d)=>d.label+' '+(d.score==null?'not scored':d.score)).join(', '));[2,4,6,8,10].forEach((v)=>svg.append('polygon').attr('points',rows.map((d,i)=>pt(i,v).join(',')).join(' ')).style('fill','none').style('stroke','rgba(39,39,37,.14)'));rows.forEach((d,i)=>{const [x,y]=pt(i,10);svg.append('line').attr('x1',cx).attr('y1',cy).attr('x2',x).attr('y2',y).style('stroke','rgba(39,39,37,.14)');});if(rows.some((d)=>d.prev!=null)){svg.append('polygon').attr('points',rows.map((d,i)=>pt(i,d.prev||0).join(',')).join(' ')).style('fill','none').style('stroke','rgba(39,39,37,.45)').style('stroke-width',1.5).style('stroke-dasharray','4 3');}svg.append('polygon').attr('points',rows.map((d,i)=>pt(i,d.score||0).join(',')).join(' ')).style('fill',L.lime).style('fill-opacity',0.7).style('stroke',L.ink).style('stroke-width',1.5);const tip=L.tip(el);const fs=W<380?11:12;rows.forEach((d,i)=>{const [x,y]=pt(i,d.score||0);svg.append('circle').attr('cx',x).attr('cy',y).attr('r',4).style('fill',L.ink);const [lx,ly]=pt(i,10);const c=Math.cos(ang(i));const sn=Math.sin(ang(i));const tx=lx+c*10;const ty=ly+sn*10;const anchor=c>0.25?'start':c<-0.25?'end':'middle';const parts=d.label.indexOf(' & ')>-1?[d.label.split(' & ')[0]+' &',d.label.split(' & ')[1]]:[d.label];const lines=parts.length+1;const lh=fs+2;const y0=sn<-0.5?ty-(lines-1)*lh:sn>0.5?ty+lh*0.8:ty-((lines-1)*lh)/2+4;const t=svg.append('text').attr('text-anchor',anchor).style('font-size',fs+'px');parts.forEach((p,j)=>t.append('tspan').attr('x',tx).attr('y',y0+j*lh).style('fill','rgba(39,39,37,.7)').text(p));t.append('tspan').attr('x',tx).attr('y',y0+parts.length*lh).style('fill',L.ink).style('font-weight','700').text(d.score==null?L.none:d.score+'/10');svg.append('circle').attr('cx',x).attr('cy',y).attr('r',16).style('fill','transparent').on('pointerenter pointermove',(ev)=>{const [mx,my]=d3.pointer(ev,el);tip.show([[null,d.label],['This month',d.score==null?L.none:d.score+'/10'],['Last month',d.prev==null?L.none:d.prev+'/10']],mx,my);}).on('pointerleave',()=>tip.hide());});});
const lineChart=(el,rows,key,xkey,xfmt,label,max)=>{const W=Math.max(260,el.clientWidth||320);const H=260;const m={t:24,r:16,b:30,l:30};const x=d3.scalePoint().domain(rows.map((d)=>d[xkey])).range([m.l,W-m.r]).padding(0.5);const y=d3.scaleLinear().domain([0,max]).range([H-m.b,m.t]);const svg=d3.select(el).append('svg').attr('viewBox',`0 0 ${W} ${H}`).attr('width','100%').attr('role','img').attr('aria-label',label+': '+rows.map((d)=>xfmt(d[xkey])+' '+d[key]).join(', '));[0,2,4,6,8,10].forEach((v)=>svg.append('line').attr('x1',m.l).attr('x2',W-m.r).attr('y1',y(v)).attr('y2',y(v)).style('stroke','rgba(39,39,37,.12)'));svg.append('g').attr('class','lg-axis').attr('transform',`translate(${m.l},0)`).call(d3.axisLeft(y).tickValues([0,2,4,6,8,10]).tickSize(0).tickPadding(8)).call((g)=>g.select('.domain').remove());const maxT=Math.max(1,Math.floor((W-m.l-m.r)/70));const step=Math.ceil(rows.length/maxT);svg.append('g').attr('class','lg-axis').attr('transform',`translate(0,${H-m.b})`).call(d3.axisBottom(x).tickValues(rows.map((d)=>d[xkey]).filter((d,i)=>i%step===0)).tickFormat(xfmt).tickSize(0).tickPadding(10)).call((g)=>g.select('.domain').remove());svg.append('path').datum(rows).attr('d',d3.line().x((d)=>x(d[xkey])).y((d)=>y(d[key]))).style('fill','none').style('stroke',L.ink).style('stroke-width',2);const tip=L.tip(el);rows.forEach((d,i)=>{svg.append('circle').attr('cx',x(d[xkey])).attr('cy',y(d[key])).attr('r',6).style('fill',L.lime).style('stroke',L.ink).style('stroke-width',1.5);if(rows.length<=12){svg.append('text').attr('x',x(d[xkey])).attr('y',y(d[key])-12).attr('text-anchor','middle').style('fill',L.ink).style('font-size','12px').style('font-weight','700').text(key==='avg'?f1(d[key]):d[key]);}const prev=rows[i-1];svg.append('circle').attr('cx',x(d[xkey])).attr('cy',y(d[key])).attr('r',16).style('fill','transparent').on('pointerenter pointermove',(ev)=>{const [mx,my]=d3.pointer(ev,el);const diff=prev?d[key]-prev[key]:null;tip.show([[null,xfmt(d[xkey])],['Score',(key==='avg'?f1(d[key]):d[key])+'/10'],['Change',diff==null?'First one':(diff>=0?'+':'-')+f1(Math.abs(diff))]],mx,my);}).on('pointerleave',()=>tip.hide());});};
dash.draw('trend',(el)=>{const h=dash.data('history');const rows=L.rows('history').filter((d)=>d.avg!=null);el.replaceChildren();if(!rows.length){L.empty(el,h.status==='error'?'Your trend couldn’t load.':h.status==='loading'?'Loading…':'Your life score line starts with your first monthly check-in.');return;}lineChart(el,rows,'avg','month',(m)=>{const p=d3.utcParse('%Y-%m')(m);return p?d3.utcFormat('%b %y')(p):m;},'Life score by month',10);});
dash.draw('weekchart',(el)=>{const w=dash.data('weekly');const rows=L.rows('weekly').filter((d)=>d.score!=null).slice(-12);el.replaceChildren();if(!rows.length){L.empty(el,w.status==='loading'?'Loading…':'Your weekly scores show up here after your first weekly check-in.');return;}lineChart(el,rows,'score','week',(s)=>{const d=L.parse(s);return d?d3.timeFormat('%b %-d')(d):s;},'Weekly score',10);});
dash.draw('historyrows',(tb)=>{const rows=L.rows('history').slice().reverse();tb.replaceChildren(...rows.map((r)=>{const tr=document.createElement('tr');tr.dataset.key=r.month;['month','avg'].concat(keys).forEach((c)=>{const td=document.createElement('td');if(c==='month'){td.textContent=L.monthLabel(r.month);}else{const v=r[c];const s=mk('span','lg-cell',v==null?L.none:c==='avg'?f1(v):String(v));if(v!=null)s.style.background=heat(v);td.append(s);}tr.append(td);});return tr;}));});
dash.draw('notes',(el)=>{const rows=L.rows('checkins').filter((r)=>r&&String(r.month||'').length===7).sort((a,b)=>(a.month<b.month?-1:1));el.replaceChildren();const r=rows[rows.length-1];if(!r)return;[['win','Biggest win'],['god','Where I saw God move'],['focus','Focus for next month']].forEach(([f,t])=>{const d=mk('div','lg-note');const p=mk('p',null,r[f]?String(r[f]):'Nothing written yet.');p.dataset.source='checkins';p.dataset.field=f;p.dataset.where='month='+encodeURIComponent(r.month);d.append(mk('h4',null,t+' · '+L.monthLabel(r.month)),p);el.append(d);});});
dash.draw('areabars',(el)=>{const rows=L.rows('dailyAreas');el.replaceChildren();if(!rows.length||!rows[0].days){L.empty(el,'Check in daily and this fills up with how often you show up for each area.');return;}rows.forEach((r)=>{const row=mk('div','lg-hit');row.dataset.source='dailyAreas';row.dataset.where='area='+r.area;const top=mk('div','lg-hit-top');const n=mk('span','lg-hit-n',r.hits+'/'+r.days+' days');n.dataset.field='hits';top.append(mk('span',null,r.label),n);const bar=mk('div','lg-bar');const s=document.createElement('span');s.style.width=(r.rate||0)+'%';bar.append(s);row.append(top,bar);el.append(row);});});
dash.draw('calendar',(el)=>{const d=L.parse(L.day)||new Date();const y=d.getFullYear(),m=d.getMonth();const first=new Date(y,m,1);const lead=(first.getDay()+6)%7;const n=new Date(y,m+1,0).getDate();const byDate={};L.rows('days').forEach((r)=>{byDate[r.date]=r;});el.replaceChildren();for(let i=0;i<lead;i+=1)el.append(mk('span','lg-cal-blank'));for(let i=1;i<=n;i+=1){const ds=y+'-'+L.pad(m+1)+'-'+L.pad(i);const r=byDate[ds];const b=mk('button','lg-cal-day',String(i));b.type='button';if(r){const hits=keys.filter((k)=>r[k]===true).length;b.style.background=`rgba(177,226,135,${0.25+0.75*hits/10})`;b.title=hits+'/10 areas';b.classList.add('lg-cal-logged');}if(ds===L.today)b.classList.add('lg-cal-today');if(ds===L.day)b.classList.add('lg-cal-sel');b.onclick=()=>{document.querySelectorAll('#daily-form [name=date]').forEach((inp)=>{inp.value=ds;inp.dispatchEvent(new Event('change'));});};el.append(b);}});
dash.draw('callabel',(el)=>{el.textContent=L.monthLabel(L.day);});
dash.draw('weeklabel',(el)=>{el.textContent=L.weekLabel(L.week);});
dash.draw('weekgrid',(el)=>{const start=L.parse(L.week)||new Date();const dates=[];for(let i=0;i<7;i+=1){const d=new Date(start);d.setDate(start.getDate()+i);dates.push(L.ymd(d));}const byDate={};L.rows('days').forEach((r)=>{byDate[r.date]=r;});el.replaceChildren();const t=mk('table','lg-table lg-wk');const th=document.createElement('thead');const hr=document.createElement('tr');hr.append(mk('th',null,'Area'));dates.forEach((ds)=>{const p=L.parse(ds);hr.append(mk('th',null,d3.timeFormat('%a %-d')(p)));});hr.append(mk('th',null,'Total'));th.append(hr);const tb=document.createElement('tbody');L.areas.forEach(([k,label])=>{const tr=document.createElement('tr');tr.append(mk('td',null,label));let c=0;dates.forEach((ds)=>{const r=byDate[ds];const hit=r&&r[k]===true;if(hit)c+=1;tr.append(mk('td',hit?'lg-tick':'lg-dot',hit?'✓':r?'·':''));});tr.append(mk('td','lg-wk-total',c+'/7'));tb.append(tr);});t.append(th,tb);const wrap=mk('div','lg-tablewrap');wrap.append(t);el.append(wrap);});
const areaName=(k)=>{const a=L.areas.find((x)=>x[0]===k);return a?a[1]:'';};
dash.draw('winpick',(el)=>{const rows=L.rows('allWins');el.replaceChildren();if(!rows.length){L.empty(el,'Your wins will show up here. Start with one from today.');return;}const w=rows[Math.floor((L.winSeed||0)*rows.length)%rows.length];const q=mk('p','lg-win-big',String(w.text));q.dataset.source='allWins';q.dataset.field='text';q.dataset.where='id='+encodeURIComponent(w.id);el.append(q,mk('p','lg-k',L.dayLabel(w.date.length===10?w.date:w.date+'-01')+' · '+w.from+(w.area?' · '+areaName(w.area):'')));});
dash.draw('winboard',(el)=>{const st=dash.data('allWins');const rows=L.rows('allWins');el.replaceChildren();if(!rows.length){L.empty(el,st.status==='loading'?'Loading…':'No wins yet. Big or small, they all count.');return;}rows.forEach((w)=>{const c=mk('div','lg-card lg-win');const t=mk('p','lg-win-text',String(w.text));c.append(t);c.append(mk('p','lg-k',L.dayLabel(w.date)+' · '+w.from+(w.area?' · '+areaName(w.area):'')));if(w.doc){const del=mk('button','lg-link');del.type='button';twoStep(del,'Remove',async()=>{await L.remove('wins',w.doc);});c.append(del);}el.append(c);});});
const dreamRow=(id)=>L.rows('dream').find((x)=>x.id===id);
dash.onData(()=>{const d=dash.data('dream');const s=d.status==='ok'?dreamRow('state'):null;const open=!!(s&&s.unlocked);document.querySelectorAll('.lg [data-dream=locked]').forEach((el)=>{el.hidden=open;});document.querySelectorAll('.lg [data-dream=open]').forEach((el)=>{el.hidden=!open;});});
dash.draw('dreamname',(el)=>{const s=dreamRow('state');el.textContent=s&&s.name?String(s.name):'dreamer';});
dash.draw('dreamboard',(el)=>{const h=el.dataset.h;const r=dreamRow(h);el.replaceChildren();const photos=r&&Array.isArray(r.photos)?r.photos.filter((p)=>String(p).indexOf('/')<0):[];const says=[['who','Who I am'],['feel','How I feel'],['day','A day in my life'],['step','My first step this month']].filter(([f])=>r&&r[f]);if(!photos.length&&!says.length){L.empty(el,'Close your eyes, picture her, then build this board below.');return;}if(photos.length){const grid=mk('div','lg-dream-grid');photos.forEach((id)=>{const fig=mk('div','lg-dream-ph');const img=document.createElement('img');img.src='/_blob/'+id;img.alt='Vision board photo';img.loading='lazy';const del=mk('button','lg-link lg-dream-del');del.type='button';twoStep(del,'Remove',async()=>{const row=Object.assign({},r);delete row.id;row.photos=(r.photos||[]).filter((p)=>p!==id);await L.save('dream',h,row);const a=await claude.use('assets');if(a){try{await a.delete(id);}catch(e){}}});fig.append(img,del);grid.append(fig);});el.append(grid);}says.forEach(([f,label])=>{const b=mk('div','lg-dream-block');const p=mk('p','lg-dream-say',String(r[f]));p.dataset.source='dream';p.dataset.field=f;p.dataset.where='id='+h;b.append(mk('p','lg-k',label),p);el.append(b);});});
dash.draw('memories',(el)=>{const st=dash.data('memories');const rows=L.rows('memories').filter((r)=>r&&r.date).sort((a,b)=>(a.date<b.date?1:-1));el.replaceChildren();if(!rows.length){L.empty(el,st.status==='loading'?'Loading…':'No highlights yet. Add the first moment that made you smile.');return;}const groups=d3.groups(rows,(r)=>String(r.date).slice(0,7));groups.forEach(([mo,items])=>{el.append(mk('h3','lg-mem-month',L.monthLabel(mo)));const grid=mk('div','lg-mem-grid');items.forEach((r)=>{const c=mk('div','lg-card lg-mem');if(r.imageId&&String(r.imageId).indexOf('/')<0){const img=document.createElement('img');img.src='/_blob/'+r.imageId;img.alt=r.title?String(r.title):'Highlight photo';img.loading='lazy';c.append(img);}const body=mk('div','lg-mem-body');body.append(mk('p','lg-k',L.dayLabel(r.date)));if(r.title)body.append(mk('h4',null,String(r.title)));if(r.note)body.append(mk('p','lg-mem-note',String(r.note)));const del=mk('button','lg-link');del.type='button';twoStep(del,'Remove',async()=>{await L.remove('memories',r.id);if(r.imageId){const a=await claude.use('assets');if(a){try{await a.delete(r.imageId);}catch(e){}}}});body.append(del);c.append(body);grid.append(c);});el.append(grid);});});
const dumpItem=(r,released)=>{const c=mk('div','lg-card lg-dump'+(released?' lg-dump-done':''));c.append(mk('p','lg-dump-text',String(r.text||'')));if(r.instead)c.append(mk('p','lg-dump-instead','Instead: '+String(r.instead)));c.append(mk('p','lg-k',released?'Let go '+L.dayLabel(r.releasedOn||r.date):'Added '+L.dayLabel(r.date)));const act=mk('div','lg-dump-act');if(!released){const go=mk('button','lg-btn lg-btn-sm','Let it go ✦');go.type='button';go.onclick=async()=>{go.disabled=true;const row=Object.assign({},r);delete row.id;row.released=true;row.releasedOn=L.today;try{await L.save('letgo',r.id,row);}catch(e){go.disabled=false;go.textContent='Didn’t work, try again';}};act.append(go);}const del=mk('button','lg-link');del.type='button';twoStep(del,'Delete',async()=>{await L.remove('letgo',r.id);});act.append(del);c.append(act);return c;};
dash.draw('dump',(el)=>{const st=dash.data('letgo');const rows=L.rows('letgo').filter((r)=>!r.released).sort((a,b)=>(String(a.date)<String(b.date)?1:-1));el.replaceChildren();if(!rows.length){L.empty(el,st.status==='loading'?'Loading…':'Nothing in the dump right now. Light and free.');return;}rows.forEach((r)=>el.append(dumpItem(r,false)));});
dash.draw('released',(el)=>{const rows=L.rows('letgo').filter((r)=>r.released).sort((a,b)=>(String(a.releasedOn||a.date)<String(b.releasedOn||b.date)?1:-1));el.replaceChildren();if(!rows.length){L.empty(el,'What you let go of lands here. Watch this list grow.');return;}rows.forEach((r)=>el.append(dumpItem(r,true)));});})();
